WITH store_promo_profit AS ( SELECT s.s_store_id, s.s_store_name, p.p_promo_id, SUM(ss.ss_net_profit) AS total_net_profit FROM store_sales ss JOIN store s ON ss.ss_store_sk = s.s_store_sk JOIN promotion p ON ss.ss_promo_sk = p.p_promo_sk GROUP BY s.s_store_id, s.s_store_name, p.p_promo_id ) SELECT s_store_id, s_store_name, p_promo_id, total_net_profit, CASE WHEN total_net_profit > 100000 THEN 'High' WHEN total_net_profit > 50000 THEN 'Medium' ELSE 'Low' END AS profit_category, RANK() OVER (PARTITION BY p_promo_id ORDER BY total_net_profit DESC) AS profit_rank FROM store_promo_profit ORDER BY p_promo_id, profit_rank
